 public partial class TaskMissionRunner {
  public TaskContract Contract{get;private set;}public TaskRuntimeContext Context{get;private set;}
  TaskContract _testContract;string _contractExtractionPrompt;
  readonly List<string> _recentVisitedTargets=new List<string>();string _rememberedVisitMission;
  public string[] RecentVisitedTargets {get{return _recentVisitedTargets.ToArray();}}
  void RememberVisitedTargets(){
   if(Evidence==null||Context==null||_rememberedVisitMission==Context.MissionId)return;
   _rememberedVisitMission=Context.MissionId;
   foreach(var receipt in Evidence.results){
    if(receipt.kind!="navigate"||receipt.status!="succeeded"||string.IsNullOrEmpty(receipt.target_id))continue;
    string id=receipt.target_id;if(Catalog.Get(id)==null&&Catalog.Get("anchor/"+id)!=null)id="anchor/"+id;
    if(Catalog.Get(id)==null)continue;
    _recentVisitedTargets.Remove(id);_recentVisitedTargets.Add(id);
    while(_recentVisitedTargets.Count>8)_recentVisitedTargets.RemoveAt(0);
   }
  }
  public bool SubmitContractTest(string request,string source,TaskContract contract){_testContract=contract;try{return SubmitCodeForTest(request,source);}finally{_testContract=null;}}
  void EmitRuntime(string type,string tool="",string status="",string detail=""){
   if(Context==null)return;var e=Context.Emit(type,tool,status,detail);File.AppendAllText(Path.Combine(RunDirectory,"events.jsonl"),JsonUtility.ToJson(e)+"\n",Encoding.UTF8);
  }
  IEnumerator BindContract(int generation,TaskContract fixture){
